const $=s=>document.querySelector(s);
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
const rand=arr=>arr[Math.floor(Math.random()*arr.length)];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const euros=v=>Math.round(v).toLocaleString('fr-FR')+' €';
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const fresh=()=>({stage:'setup',week:1,money:3000,rep:0,vig:0,salary:280,crew:'',avatar:AVATARS[0],rig:{gen:null},wall:{top:[],kick:[],sub2:[],sub:[]},seizures:[],subRow:1,sel:null,used:{},spot:null,lineup:null,phase:'montage',mHour:0,hour:0,sound:50,infoline:false,people:0,totalPeople:0,donations:0,fines:0,log:[],event:null,lastCategory:null,result:null});
let s;try{s=JSON.parse(localStorage.getItem(SAVE_KEY));if(!s||!s.rig||!s.wall||!Array.isArray(s.wall.top)||(s.wall.sub2=s.wall.sub2||[],false)|| JSON.stringify(s.wall).includes('mth4654')||!['setup','hideout','map','lineup','party','summary'].includes(s.stage))s=fresh()}catch{s=fresh()}
const save=()=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify(s))}catch{}};
s.seizures=s.seizures||[];
let showJudge=false;
// Suivi judiciaire du matériel saisi : l'état évolue chaque semaine
const CASE_STATUS={nonews:['📭','Pas de nouvelles'],hearing:['📅','Audience programmée'],return:['📦','Restitution programmée'],destroy:['🔥','Destruction du matériel'],returned:['✅','Matériel restitué'],destroyed:['💥','Matériel détruit']};
const caseOpen=c=>!['returned','destroyed'].includes(c.status);
function restoreCase(c){for(const u of c.items){const def=rigDef(u.slot,u.id);if(!def)continue;if(canPlace(u.slot,u.id)){s.wall[u.slot==='sub'?'sub2':u.slot].push({slot:u.slot,id:u.id,cond:u.cond})}else s.money+=sellPrice(def,u.cond)}
balanceSubs();
if(c.gen){const gd=rigDef('gen',c.gen.id);if(gd){if(!s.rig.gen)s.rig.gen=c.gen;else s.money+=sellPrice(gd,c.gen.cond)}}}
function advanceCases(){for(const c of s.seizures){if(c.week===s.week||!caseOpen(c))continue;const before=c.status;
if(c.status==='nonews'){if(Math.random()<.5)c.status='hearing'}
else if(c.status==='hearing')c.status=Math.random()<.55?'return':'destroy';
else if(c.status==='return'){restoreCase(c);c.status='returned'}
else if(c.status==='destroy')c.status='destroyed';
if(c.status!==before)s.judgeNew=true}}
function caseItems(c){const n={};for(const u of c.items){const d=rigDef(u.slot,u.id);if(d)n[d.name]=(n[d.name]||0)+1}if(c.gen){const g=rigDef('gen',c.gen.id);if(g)n['Groupe '+g.name]=1}return Object.entries(n).map(([k,v])=>`${k}${v>1?' ×'+v:''}`)}
function judgeModal(){if(!showJudge)return '';const list=[...s.seizures].reverse().map(c=>{const st=CASE_STATUS[c.status],items=caseItems(c);return `<div class="judgecase ${c.status}"><div class="judgehead"><b>Week-end n° ${c.week}</b><span class="judgestatus">${st[0]} ${st[1]}</span></div><ul>${items.map(i=>`<li>${escapeHtml(i)}</li>`).join('')||'<li>Aucun matériel</li>'}</ul></div>`}).join('');
return `<div class="judgemodal"><div class="judgeback" data-act="judgeclose"></div><div class="judgebox" role="dialog" aria-label="Matériel saisi"><h2>⚖️ Matériel en saisie</h2>${list||'<p class="muted">Aucun matériel saisi pour le moment.</p>'}<div class="toolbar"><button class="btn secondary" data-act="judgeclose">Fermer</button></div></div></div>`}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&showJudge){showJudge=false;render()}});
const condFactor=c=>.35+.65*c/100;
// Un mur = plusieurs lignes empilées (ligne 0 en bas). Chaque ligne a une largeur limitée, chaque caisson occupe une part.
const WALL_ROWS=['top','kick','sub2','sub'],ROW_W=800,UNIT_W={top:58,kick:78,sub:122},UNIT_H={top:62,kick:60,sub:60};
const itemWidth=(slot,d)=>d.width||UNIT_W[slot],itemHeight=(slot,d)=>d.height||UNIT_H[slot];
// Les subs se posent sur deux lignes : la ligne 2 doit reposer sur la ligne 1 (jamais plus large qu'elle)
// Les subs se répartissent automatiquement et à parts égales sur les deux lignes (ligne 1 au sol, ligne 2 dessus)
const balanceSubs=()=>{const all=[...s.wall.sub,...s.wall.sub2],h=Math.ceil(all.length/2);s.wall.sub=all.slice(0,h);s.wall.sub2=all.slice(h)};
const canPlace=(slot,id)=>{const def=rigDef(slot,id);if(!def)return false;if(slot==='sub'){const units=[...s.wall.sub,...s.wall.sub2,{slot,id,cond:100}],h=Math.ceil(units.length/2);return rowWidth(units.slice(0,h))<=ROW_W&&rowWidth(units.slice(h))<=ROW_W}return rowWidth(s.wall[slot])+itemWidth(slot,def)<=ROW_W};
const rowWidth=row=>row.reduce((t,u)=>t+itemWidth(u.slot,rigDef(u.slot,u.id)),0);
const wallUnits=()=>WALL_ROWS.flatMap(k=>s.wall[k]);
function rigStats(){let need=0,sum=0;const units=wallUnits().filter(u=>u.cond>0);
for(const u of units)need+=rigDef(u.slot,u.id).kw;
const g=s.rig.gen,gd=g&&rigDef('gen',g.id),genKw=gd&&g.cond>0?gd.kw*(.5+.5*g.cond/100):0;const ratio=need===0?1:Math.min(1,genKw/need);
for(const u of units)sum+=rigDef(u.slot,u.id).pow*condFactor(u.cond)*ratio;
return {need,genKw,ratio,sum,count:units.length,sound:sum?clamp(Math.round(12+88*(1-Math.exp(-sum/45)))):0,capBonus:Math.round(sum*5),attract:Math.round(sum*.3),fuel:gd?Math.round(gd.kw*1.5):0}}
const rigReady=()=>{const u=wallUnits();return !!(s.rig.gen&&u.some(x=>x.slot==='top')&&u.some(x=>x.slot!=='top'))};
const unitPrice=(u)=>rigDef(u.slot,u.id).price;
const repairCost=(def,cond)=>Math.round(def.price*(100-cond)/100*.4);
const sellPrice=(def,cond)=>Math.round(def.price*.3*cond/100);
function removeRetiredRigItems(){
const retired={top:{turbosound:{name:'Turbosound',price:350}},kick:{punch:{name:'Punch Lorrain',price:550},mhb4818:{name:'MHB 4818',price:700}},sub:{mhb46:{name:'MHB 46',price:560},mth46vs:{name:'MTH 46VS',price:780},mtl246:{name:'MTL 246',price:850}}};
let removed=0,refund=0;
for(const [slot,items] of Object.entries(retired)){const rows=slot==='sub'?['sub','sub2']:[slot];for(const row of rows){s.wall[row]=s.wall[row].filter(unit=>{const def=items[unit.id];if(!def)return true;removed++;refund+=sellPrice(def,unit.cond);return false})}}
if(removed){s.money+=refund;s.sel=null;s.log=s.log||[];s.log.unshift(`${removed} ancien(s) caisson(s) retiré(s) du catalogue ; remboursement occasion : ${euros(refund)}.`);balanceSubs();save()}
}
removeRetiredRigItems();
const selTarget=()=>{if(!s.sel)return null;if(s.sel==='gen')return s.rig.gen?{slot:'gen',obj:s.rig.gen}:null;const [r,i]=s.sel.split(':');const u=s.wall[r]&&s.wall[r][Number(i)];return u?{slot:u.slot,obj:u,r,i:Number(i)}:null};
const usedCond=key=>{if(!s.used[key])s.used[key]=Math.round(25+Math.random()*45);return s.used[key]};
const cap=()=>s.spot.capacity+rigStats().capBonus;
const lineup=()=>LINEUPS.find(l=>l.id===s.lineup)||LINEUPS[0];
function escapeHtml(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function card(title,body,cls=''){return `<section class="panel ${cls}"><h2>${title}</h2>${body}</section>`}
function stats(){return `<div class="stats"><div class="stat"><span>💰 Caisse</span><b>${euros(s.money)}</b></div><div class="stat"><span>🔥 Réputation</span><b>${s.rep}/100</b></div><div class="stat"><span>👮 Vigilance</span><b>${s.vig}/100</b></div><div class="stat"><span>📅 Week-end</span><b>n° ${s.week}</b></div></div>`}
function header(){const crew=s.stage==='setup'?'':`<div class="crew"><span class="avatar">${s.avatar}</span><b>${escapeHtml(s.crew)}</b></div>`;return `<header><div><div class="brand">ACID<em>//</em>RAVE</div><div class="tag">STRATÉGIE • ÉVÉNEMENTS • PROTOTYPE V0.2</div></div>${crew}<div class="headbtns">${s.stage==='setup'?'':`<button class="btn secondary judgebtn" data-act="judge" title="Matériel en saisie" aria-label="Matériel en saisie">⚖️${s.seizures.some(caseOpen)||s.judgeNew?`<i class="judgedot ${s.judgeNew?'new':''}"></i>`:''}</button>`}<button class="btn secondary" data-act="reset">Nouvelle partie</button></div></header>${stats()}`}
const openSlots=new Set();
document.addEventListener('toggle',e=>{const d=e.target;if(d.dataset&&d.dataset.slot){d.open?openSlots.delete(d.dataset.slot):openSlots.add(d.dataset.slot)}},true);
function condBar(c){const cls=c>60?'ok':c>30?'mid':'bad';return `<span class="cond"><i class="${cls}" style="width:${c}%"></i></span>`}
const genIdx={gs:4,gb:0};
const genGroups=()=>{const it=RIG_SLOTS.find(x=>x.id==='gen').items;return [{id:'gs',title:'Portable',items:it.filter(d=>d.kw<7)},{id:'gb',title:'Groupe capoté',items:it.filter(d=>d.kw>=7)}]};
function genBody(g){const d=g.items[genIdx[g.id]],key='gen:'+d.id,uc=usedCond(key),up=usedPrice(d,uc);
return `<div class="art">${speakerSvg('gen',d)}</div><strong>${d.name}</strong><small>${g.title} · ${d.kw} kW</small><div class="buyrow"><button class="buy" data-act="rigbuy" data-id="${key}" data-mode="new" ${s.money<d.price?'disabled':''}>Buy<br>${euros(d.price)}</button><button class="buy alt" data-act="rigbuy" data-id="${key}" data-mode="used" ${s.money<up?'disabled':''}>Occasion<br>${euros(up)} · ${uc}%</button></div>`}
function genSlot(sl){const cards=genGroups().map(g=>{const own=s.rig.gen&&g.items.some(d=>d.id===s.rig.gen.id);const last=g.items.length-1;
return `<div class="mini genmini ${own?'own':''}" data-grp="${g.id}">${own?`<span class="badge">×1</span>`:''}<div class="genbody">${genBody(g)}</div><input type="range" class="genrange" data-grp="${g.id}" min="0" max="${last}" step="1" value="${genIdx[g.id]}" aria-label="Puissance ${g.title}"><div class="genscale">${g.items.map((d,i)=>`<span class="tick ${i===genIdx[g.id]?'on':''}" style="left:calc(8px + (100% - 16px) * ${i/last})"><i></i>${d.kw}</span>`).join('')}</div></div>`}).join('');
return `<details class="slot-box" ${openSlots.has(sl.id)?'':'open'} data-slot="${sl.id}"><summary>${sl.emoji} ${sl.label}</summary><div class="minigrid gengrid">${cards}</div></details>`}
document.addEventListener('input',e=>{const r=e.target;if(!r.classList||!r.classList.contains('genrange'))return;const g=genGroups().find(x=>x.id===r.dataset.grp);if(!g)return;genIdx[g.id]=Number(r.value);const body=r.closest('.mini').querySelector('.genbody');if(body)body.innerHTML=genBody(g);r.closest('.mini').querySelectorAll('.tick').forEach((t,i)=>t.classList.toggle('on',i===genIdx[g.id]))});
function rigSlot(sl){if(sl.id==='gen')return genSlot(sl);const full=sl.items.every(d=>!canPlace(sl.id,d.id));const owned={};for(const u of wallUnits())if(u.slot===sl.id)owned[u.id]=(owned[u.id]||0)+1;
const list=sl.items.map(d=>{const key=sl.id+':'+d.id,uc=usedCond(key),up=usedPrice(d,uc),n=owned[d.id]||0,itemFull=!canPlace(sl.id,d.id);return `<div class="mini ${n?'own':''}">${n?`<span class="badge">×${n}</span>`:''}<div class="art">${speakerSvg(sl.id,d)}</div><strong>${d.name}</strong><small>${sl.id==='gen'?`${d.kw} kW`:`Puiss. ${d.pow} · ${d.kw} kW · larg. ${itemWidth(sl.id,d)} × haut. ${itemHeight(sl.id,d)} cm`}</small><div class="buyrow"><button class="buy" data-act="rigbuy" data-id="${key}" data-mode="new" ${s.money<d.price||itemFull?'disabled':''}>Buy<br>${euros(d.price)}</button><button class="buy alt" data-act="rigbuy" data-id="${key}" data-mode="used" ${s.money<up||itemFull?'disabled':''}>Occasion<br>${euros(up)} · ${uc}%</button></div></div>`}).join('');
return `<details class="slot-box" ${openSlots.has(sl.id)?'':'open'} data-slot="${sl.id}"><summary>${sl.emoji} ${sl.label}${sl.id==='gen'?'':` — ${sl.id==='sub'?s.wall.sub.length+s.wall.sub2.length:s.wall[sl.id].length} posé(s) · ${sl.id==='sub'?`ligne 1 ${rowWidth(s.wall.sub)} cm · ligne 2 ${rowWidth(s.wall.sub2)} cm`:`${rowWidth(s.wall[sl.id])}/${ROW_W} cm`}${full?' (place indisponible)':''}`}</summary><div class="minigrid">${list}</div></details>`}
function selPanel(){const t=selTarget();if(!t)return `<div class="selpanel muted tiny">Clique sur un caisson ou la génératrice pour le réparer ou le revendre. Chaque achat s’ajoute sur la ligne de son type.</div>`;const def=rigDef(t.slot,t.obj.id),rc=repairCost(def,t.obj.cond);
return `<div class="selpanel"><div class="art sm">${speakerSvg(t.slot,def,t.obj.cond)}</div><div><b>${def.name}</b> <small>état ${t.obj.cond}%</small>${condBar(t.obj.cond)}</div><div class="mini-actions"><button class="btn secondary sm" data-act="rigrepair" ${t.obj.cond>=100||s.money<rc?'disabled':''}>🔧 Réparer ${euros(rc)}</button><button class="btn secondary sm" data-act="rigsell">Revendre ${euros(sellPrice(def,t.obj.cond))}</button></div></div>`}
function wallControls(){let all=0;const units=wallUnits().map(u=>({u,d:rigDef(u.slot,u.id)}));if(s.rig.gen)units.push({u:s.rig.gen,d:rigDef('gen',s.rig.gen.id)});for(const x of units)all+=repairCost(x.d,x.u.cond);
return `<div class="wallbar"><button class="btn secondary sm" data-act="repairall" ${all<=0||s.money<all?'disabled':''}>🔧 Tout réparer ${euros(all)}</button></div>${selPanel()}`}
function configurator(extra='',showDone=true){const r=rigStats();const warn=!rigReady()?'<div class="info">Il te faut au minimum une génératrice, un top et un kick ou un sub.</div>':r.ratio<1?`<div class="info">⚡ Génératrice trop faible : ${r.genKw.toFixed(1)} kW disponibles pour ${r.need.toFixed(1)} kW demandés — le son est bridé à ${Math.round(r.ratio*100)} %.</div>`:'';
const sum=`<div class="rigsum"><div class="metric"><span>🔊 Qualité du son estimée</span><b>${r.sound}/100</b></div><div class="metric"><span>🧱 Caissons</span><b>${r.count}</b></div><div class="metric"><span>⚡ Électricité</span><b>${r.genKw.toFixed(1)} / ${r.need.toFixed(1)} kW</b></div><div class="metric"><span>👥 Capacité bonus</span><b>+${r.capBonus}</b></div></div>`;
if(showDone&&s.rigDone&&rigReady())return `<div class="walltop">${wallSvg()}</div>${sum}${warn}<div class="toolbar"><button class="btn secondary" data-act="rigedit">✏️ Modifier le sound</button>${extra}</div>`;
const doneBtn=showDone&&rigReady()?'<div class="toolbar"><button class="btn" data-act="rigdone">✅ Configuration terminée</button></div>':'';
return `<div class="walltop">${wallSvg()}${wallControls()}</div>${RIG_SLOTS.map(rigSlot).join('')}<div class="tiny muted">Le mur a une ligne par type (Top, Kick, Sub) : tu peux y aligner autant de caissons que la largeur le permet (${ROW_W/100} m de large ; top ${UNIT_W.top} × ${UNIT_H.top} cm, kicks dessinés à l’échelle — le B115 mesure 118 × 46,8 cm, le MKH 230 mesure ${UNIT_W.kick} × ${UNIT_H.kick} cm ; subs dessinés à l’échelle — le MN 246 mesure 118 × 60 cm). L’occasion est moins chère mais déjà usée ; le matos s’use à chaque soirée et lors des pannes, et ne fonctionne plus à 0 %.</div><div class="rigsum"><div class="metric"><span>🔊 Qualité du son estimée</span><b>${r.sound}/100</b></div><div class="metric"><span>🧱 Caissons</span><b>${r.count}</b></div><div class="metric"><span>⚡ Électricité</span><b>${r.genKw.toFixed(1)} / ${r.need.toFixed(1)} kW</b></div><div class="metric"><span>👥 Capacité bonus</span><b>+${r.capBonus}</b></div><div class="metric"><span>⛽ Carburant par soirée</span><b>${euros(r.fuel)}</b></div></div>${warn}${doneBtn}`}
const condColor=c=>c>60?'#c4f85b':c>30?'#f0b84a':'#e0566e';
// Visuel vectoriel d'une enceinte ; la largeur suit la puissance
// Façade de top type MT130 (58 × 62 cm) : cornet carré en haut, bas en trois panneaux avec fente et boomer central
function topFront(x,y,w,h,c,sw){const k=`translate(${x} ${y}) scale(${w/58} ${h/62})`;
return `<g transform="${k}" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><rect x="0" y="0" width="58" height="62" rx="1.5"/><rect x="9" y="4" width="40" height="26"/><path d="M9 4 L22 14 M49 4 L36 14 M9 30 L22 20 M49 30 L36 20"/><rect x="22" y="14" width="14" height="6" rx="1"/><line x1="0" y1="35" x2="58" y2="35"/><line x1="20" y1="35" x2="20" y2="62"/><line x1="38" y1="35" x2="38" y2="62"/><rect x="25" y="39" width="8" height="19"/><circle cx="29" cy="49" r="4" fill="${c}"/></g>`}
// Funktion One F1-style front: large faceted horn over a tapered lower cabinet.
function f1Front(x,y,w,h,c,sw){const k=`translate(${x} ${y}) scale(${w/58} ${h/62})`;
return `<g transform="${k}" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><path d="M2 1 H56 V47 L43 61 H15 L2 47 Z"/><rect x="7" y="5" width="44" height="32"/><path d="M7 5 L21 16 H37 L51 5 M7 37 L21 26 H37 L51 37 M7 21 H51 M21 16 L16 21 L21 26 H37 L42 21 L37 16 Z"/><path d="M24 19 H34 V23 H24 Z"/><rect x="20" y="42" width="18" height="12" rx="1"/><path d="M20 42 L29 48 L38 42 M20 54 L29 48 L38 54"/><circle cx="29" cy="48" r="2.2" fill="${c}"/></g>`}
// Façade de kick type MKH (78 × 60 cm) : deux panneaux à bandes horizontales, fente verticale centrale, socle
function kickFront(x,y,w,h,c,sw){const k=`translate(${x} ${y}) scale(${w/78} ${h/60})`;
return `<g transform="${k}" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><rect x="0" y="0" width="78" height="60"/><line x1="1.5" y1="10" x2="76.5" y2="10"/><line x1="1.5" y1="16.5" x2="76.5" y2="16.5"/><rect x="38" y="2" width="2.2" height="40" fill="${c}"/><line x1="0" y1="54" x2="78" y2="54"/><line x1="0" y1="56.5" x2="78" y2="56.5"/><line x1="1.5" y1="0" x2="1.5" y2="60"/><line x1="76.5" y1="0" x2="76.5" y2="60"/></g>`}
function b115Front(x,y,w,h,c,sw){const k=`translate(${x} ${y}) scale(${w/118} ${h/46.8})`;
return `<g transform="${k}" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><rect x="1" y="1" width="116" height="44.8"/><path d="M2 2 H23 V44.8 H2 M95 2 H116 V44.8 H95 M23 2 V44.8 M30 2 V44.8 M88 2 V44.8 M95 2 V44.8" /><circle cx="59" cy="23.4" r="17" stroke-dasharray="2 1"/><line x1="2" y1="23.4" x2="42" y2="23.4" stroke-dasharray="1 1" opacity=".55"/><line x1="76" y1="23.4" x2="116" y2="23.4" stroke-dasharray="1 1" opacity=".55"/></g>`}
// Façade de sub type MHB 4818 (122 × 60 cm) : deux chambres latérales à tablette, évent central étroit
function subFront(x,y,w,h,c,sw){const k=`translate(${x} ${y}) scale(${w/122} ${h/60})`;
return `<g transform="${k}" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><rect x="0" y="0" width="122" height="60"/><line x1="0" y1="55" x2="122" y2="55"/><line x1="9" y1="0" x2="9" y2="55"/><line x1="15" y1="0" x2="15" y2="55"/><line x1="107" y1="0" x2="107" y2="55"/><line x1="113" y1="0" x2="113" y2="55"/><line x1="48" y1="0" x2="48" y2="55"/><line x1="74" y1="0" x2="74" y2="55"/><line x1="4" y1="30" x2="48" y2="30"/><line x1="74" y1="30" x2="118" y2="30"/><rect x="56" y="6" width="9" height="47" fill="${c}" fill-opacity=".35"/></g>`}
// MN 246 chamber layout, drawn to its 118 × 60 cm footprint.
function mn246Front(x,y,w,h,c,sw){const k=`translate(${x} ${y}) scale(${w/118} ${h/60})`;
return `<g transform="${k}" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><rect x="1" y="1" width="116" height="58" fill="none"/><rect x="15" y="2" width="7" height="56" fill="${c}" fill-opacity=".35"/><rect x="96" y="2" width="7" height="56" fill="${c}" fill-opacity=".35"/><path d="M1 2 H15 M1 58 H15 M103 2 H117 M103 58 H117" fill="none"/><path d="M22 4 H36 L49 12 L56 22 L59 27 V33 L56 38 L49 48 L36 56 H22 M96 4 H82 L69 12 L62 22 L59 27 M96 56 H82 L69 48 L62 38 L59 33" fill="none"/><path d="M25 8 H35 L46 15 L52 23 M25 52 H35 L46 45 L52 37 M93 8 H83 L72 15 L66 23 M93 52 H83 L72 45 L66 37" fill="none"/><path d="M37 16 L47 22 V28 H39 L32 22 Z M37 44 L47 38 V32 H39 L32 38 Z M81 16 L71 22 V28 H79 L86 22 Z M81 44 L71 38 V32 H79 L86 38 Z" fill="none"/><line x1="2" y1="29" x2="116" y2="29" stroke-dasharray="1 1" opacity=".45"/><line x1="2" y1="31" x2="116" y2="31" stroke-dasharray="1 1" opacity=".45"/></g>`}
// Groupe électrogène portable (< 7 kW) vu de côté : cage tubulaire, réservoir, moteur, panneau de prises (viewBox 100 × 70)
function genSide(x,y,w,h,c,sw){return `<g transform="translate(${x} ${y}) scale(${w/100} ${h/70})" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"><path d="M6 66 L6 12 Q6 4 14 4 L86 4 Q94 4 94 12 L94 66"/><line x1="2" y1="66" x2="98" y2="66"/><rect x="14" y="10" width="72" height="16" rx="6"/><rect x="14" y="30" width="30" height="30" rx="3"/><circle cx="29" cy="45" r="8"/><rect x="48" y="40" width="20" height="20"/><line x1="48" y1="50" x2="68" y2="50"/><rect x="71" y="30" width="15" height="30" rx="2"/><circle cx="78.5" cy="40" r="3"/><circle cx="78.5" cy="51" r="3"/></g>`}
// Groupe capoté (≥ 7 kW) : caisson insonorisé, socle noir, panneau logo, deux portes et grille d'aération (viewBox 100 × 56)
function genBig(x,y,w,h,c,sw){return `<g transform="translate(${x} ${y}) scale(${w/100} ${h/56})" fill="none" stroke="${c}" stroke-width="${sw}" vector-effect="non-scaling-stroke" stroke-linejoin="round"><rect x="0" y="0" width="100" height="44" rx="1.5"/><rect x="0" y="44" width="100" height="12" fill="${c}" fill-opacity=".35"/><rect x="5" y="5" width="30" height="32"/><path d="M10 20 Q20 10 30 18 Q22 24 10 20 Z"/><line x1="8" y1="31" x2="32" y2="31"/><rect x="40" y="5" width="22" height="34"/><rect x="64" y="5" width="16" height="34"/><rect x="68" y="10" width="8" height="8"/><rect x="85" y="5" width="11" height="34"/><path d="M85 10 H96 M85 15 H96 M85 20 H96 M85 25 H96 M85 30 H96 M85 35 H96"/></g>`}
function speakerSvg(slot,d,cond){const c=cond==null?'#8f8cae':condColor(cond),w=60+(d.pow||4)*3.5;const x=(120-w)/2;let b='';
if(slot==='top'){const fx=60-29*.95,fy=9,fw=58*.95,fh=62*.95;b=`<rect x="${fx}" y="${fy}" width="${fw}" height="${fh}" fill="#1d1e36"/>`+(d.id==='f1'?f1Front(fx,fy,fw,fh,c,2):topFront(fx,fy,fw,fh,c,2))}
else if(slot==='kick'){const sw=100,sh=sw*itemHeight(slot,d)/itemWidth(slot,d),sx=10,sy=(80-sh)/2;b=`<rect x="${sx}" y="${sy}" width="${sw}" height="${sh}" fill="#1d1e36"/>`+(d.id==='b115'?b115Front(sx,sy,sw,sh,c,2):kickFront(sx,sy,sw,sh,c,2))}
else if(slot==='sub'){const sw=100,sh=sw*itemHeight(slot,d)/itemWidth(slot,d),sx=10,sy=(80-sh)/2;b=`<rect x="${sx}" y="${sy}" width="${sw}" height="${sh}" fill="#1d1e36"/>`+(d.id==='mn246'?mn246Front(sx,sy,sw,sh,c,2):subFront(sx,sy,sw,sh,c,2))}
else if(d.kw<7){b=genSide(15,6,90,66,c,2.5)}
else{b=`<rect x="8" y="14" width="104" height="58" fill="#1d1e36"/>`+genBig(10,16,100,56,c,2)}
return `<svg viewBox="0 0 120 80" role="img" aria-label="${escapeHtml(d.name)}">${b}</svg>`}
// Mur de son : chaque ligne est empilée (ligne 1 en bas), les caissons se posent côte à côte tant que la largeur le permet
function wallSvg(){const SC=1.1,RH=76,PAD=190,GH=56,W=ROW_W*SC+PAD+20,WH=WALL_ROWS.length*(RH+6)+6,H=WH+GH+10;let out='';
const labels={top:'TOP',kick:'KICK',sub2:'SUB 2',sub:'SUB 1'};
WALL_ROWS.forEach((k,r)=>{const row=s.wall[k],y=6+r*(RH+6);
out+=`<rect x="${PAD}" y="${y}" width="${ROW_W*SC}" height="${RH}" rx="4" fill="none" stroke="#4a4864" stroke-width="1.5" stroke-dasharray="4 4"/><text x="${PAD-8}" y="${y+RH/2+4}" text-anchor="end" font-size="11" font-weight="800" fill="#9b9cb3">${labels[k]}</text>`;
let x=PAD+(ROW_W-rowWidth(row))*SC/2;
row.forEach((u,i)=>{const d=rigDef(u.slot,u.id),unitW=itemWidth(u.slot,d),unitH=itemHeight(u.slot,d),w=unitW*SC,h=unitH*SC,uy=y+RH-6-h,sel=s.sel===k+':'+i,broken=u.cond<=0,c=broken?'#ff6b7f':'#fff';
const ic=u.slot==='top'?(u.id==='f1'?f1Front:topFront)(x,uy,w,h,c,1.6):u.slot==='kick'?(u.id==='b115'?b115Front(x,uy,w,h,c,1.6):kickFront(x,uy,w,h,c,1.6)):u.id==='mn246'?mn246Front(x,uy,w,h,c,1.6):subFront(x,uy,w,h,c,1.6);
out+=`<g data-act="unitsel" data-id="${k}:${i}" class="unit"><title>${escapeHtml(d.name)} — ${u.cond}% — ${unitW} × ${unitH} cm</title><rect x="${x}" y="${uy}" width="${w}" height="${h}" fill="${broken?'#3a1a24':'#1d1e36'}"/>${ic}${sel?`<rect x="${x-3}" y="${uy-3}" width="${w+6}" height="${h+6}" fill="none" stroke="#c8f75a" stroke-width="2.5" rx="3"/>`:''}</g>`;x+=w});
if(!row.length)out+=`<text x="${PAD+ROW_W*SC/2}" y="${y+RH/2+4}" text-anchor="middle" font-size="11" fill="#7b7896" pointer-events="none">aucun ${labels[k].toLowerCase()}</text>`});
const g=s.rig.gen,gd=g&&rigDef('gen',g.id),gc=g?condColor(g.cond):'#5b5876',gsel=s.sel==='gen',subY=6+3*(RH+6),floor=subY+RH-6;
// Gabarit humain de 165 cm, à la même échelle que les caissons, posé au niveau du sol de la ligne Sub
out+=`<g transform="translate(60 ${floor}) scale(${SC})" fill="none" stroke="#9b9cb3" stroke-width="1.4" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round" pointer-events="none"><circle cx="0" cy="-155" r="10"/><path d="M-6 -143 L6 -143 L18 -125 L16 -85 L-16 -85 L-18 -125 Z"/><path d="M-16 -85 L-14 0 M-2 -85 L-2 0 M2 -85 L2 0 M16 -85 L14 0"/><path d="M-18 -125 L-24 -75 M18 -125 L24 -75"/></g><text x="60" y="${floor-165*SC-4}" text-anchor="middle" font-size="10" font-weight="800" fill="#9b9cb3">165 cm</text><line x1="20" y1="${floor-165*SC}" x2="${PAD+ROW_W*SC}" y2="${floor-165*SC}" stroke="#c8f75a" stroke-width="1" stroke-dasharray="5 4" opacity=".7" pointer-events="none"/>`;
const small=g&&gd.kw<7;
const gw=g?(small?64:96):64,gh=g?(small?45:54):45,gx=PAD+ROW_W*SC-gw,gy=H-6-gh;
out+=`<g data-act="unitsel" data-id="gen" class="unit">${g?`<title>${escapeHtml(gd.name)} — ${g.cond}%</title><rect x="${gx}" y="${gy}" width="${gw}" height="${gh}" fill="#1d1e36"/>${small?genSide(gx,gy,gw,gh,'#fff',1.6):genBig(gx,gy,gw,gh,'#fff',1.6)}<text x="${gx-8}" y="${gy+gh/2+4}" text-anchor="end" font-size="11" font-weight="800" fill="#fff">${gd.kw} kW</text>`:`<rect x="${gx}" y="${gy}" width="${gw}" height="${gh}" rx="4" fill="none" stroke="#5b5876" stroke-width="1.5" stroke-dasharray="4 4"/><text x="${gx+gw/2}" y="${gy+gh/2+4}" text-anchor="middle" font-size="9" fill="#7b7896">⚡ géné</text>`}</g>`;
return `<svg class="wall" viewBox="0 0 ${W} ${H}" role="img" aria-label="Ton mur de son">${out}</svg>`}
function setup(){if(s.setupStep===2&&s.crew.trim())return setupSound();return card('🎤 Fonde ton crew',`<div class="stepper"><span class="on">1 · Crew</span><span>2 · Sound</span><span>3 · Menu principal</span></div><p data-type>Bienvenue dans le milieu. Choisis ton nom de crew, ton avatar et investis ton cash de départ dans ton sound.</p><label class="label" for="crew">Nom du crew <span class="req">* obligatoire</span></label><div class="namerow"><input id="crew" class="input ${s.crew.trim()?'':'invalid'}" maxlength="32" required aria-required="true" aria-describedby="crewhint" placeholder="ex : Kicktek Sound System" value="${escapeHtml(s.crew)}" autocomplete="off"><button class="btn secondary" data-act="randname">🎲 Aléatoire</button></div><div id="crewhint" class="crewhint" ${s.crew.trim()?'hidden':''}>⚠️ Donne un nom à ton crew pour pouvoir lancer la partie (ou clique sur « Aléatoire »).</div><div class="label">Avatar</div><div class="avatars">${AVATARS.map(a=>`<button class="avatar-btn ${a===s.avatar?'sel':''}" data-act="avatar" data-id="${a}" aria-label="Avatar ${a}">${a}</button>`).join('')}</div><div class="toolbar"><button id="startbtn" class="btn" data-act="setupnext" ${s.crew.trim()?'':'disabled'}>Suivant : monter mon sound →</button></div>`)}
function setupSound(){return card('🔊 Monte ton sound',`<div class="stepper"><span class="done">1 · Crew</span><span class="on">2 · Sound</span><span>3 · Menu principal</span></div><p data-type>Investis ton cash de départ : <b class="good">${euros(s.money)}</b>. Il te faut au minimum une génératrice, un top et un kick ou un sub.</p>${configurator('',false)}<div class="toolbar"><button class="btn secondary" data-act="setupback">← Crew</button><button class="btn" data-act="startcrew" ${s.crew.trim()&&rigReady()?'':'disabled'}>Valider mon sound → menu principal</button></div>`)}
function hideout(){return card('🏚️ La planque',`<p data-type>Prépare ton sound. Tu touches ${euros(s.salary)} de salaire chaque semaine après une fête. La caisse ne peut pas passer sous zéro pour acheter du matériel.</p>${configurator('<button class="btn play" data-act="tomap">▶ Jouer : choisir un lieu</button>')}`)}
function map(){return card('🗺️ Choisir un spot',`<p data-type>Chaque lieu a une capacité, un coût d’installation et un niveau de risque. Le placement du sound est abstrait dans cette version.</p><div class="grid">${SPOTS.map(x=>`<button class="option" data-act="spot" data-id="${x.id}" ${s.money<x.cost+rigStats().fuel?'disabled':''}><strong>${x.emoji} ${x.name}</strong><small>${x.detail}</small><small>👥 Capacité ${x.capacity+rigStats().capBonus}<br>⚠️ Exposition ${x.risk}/100 · Attrait +${x.appeal}</small><span class="price">Installation ${euros(x.cost)}</span></button>`).join('')}</div><div class="toolbar"><button class="btn secondary" data-act="back">← Planque</button></div>`)}
function lineupStage(){return card(`🎧 Line up — ${s.spot.name}`,`<p data-type>Quel style va faire vibrer le dancefloor ? Le line up change l’affluence, les dons, la discrétion et le risque d’imprévus.</p><div class="grid grid4">${LINEUPS.map(l=>`<button class="option" data-act="lineup" data-id="${l.id}" ${s.money<s.spot.cost+rigStats().fuel?'disabled':''}><strong>${l.emoji} ${l.name}</strong><small>${l.detail}</small><small>👥 Public ×${l.arrival}<br>🎁 Dons ×${l.don}<br>👮 Vigilance ${l.vigH>=0?'+':''}${l.vigH}/h</small></button>`).join('')}</div><div class="info">Installer ${s.spot.name} coûte ${euros(s.spot.cost)}. Ensuite : ${MONTAGE_HOURS} heures de montage, puis ${PARTY_HOURS} heures de fête.</div><div class="toolbar"><button class="btn secondary" data-act="tomap">← Lieux</button></div>`)}
function probabilities(){const montage=s.phase==='montage',L=lineup();let p,good;if(montage){p=clamp(34-s.rep*.28+s.vig*.18,8,65);good=clamp(12+s.rep*.35,5,60)}else{p=clamp(18+s.vig*.52-s.rep*.07+L.prob,8,80);good=clamp(15+s.rep*.28-s.vig*.12+L.good,5,60)}return {problem:p,positive:good,neutral:100-p-good}}
function nextEvent(){if(s.stage==='party'&&s.phase==='party'&&s.hour>=PARTY_HOURS){s.event=null;s.decide=true;return}drawEvent()}
function advance(){nextEvent()}
function stopParty(){s.waiting=false;s.decide=false;s.event=null;s.stage='summary';finish()}
function endEarly(){if(s.phase==='party'&&s.hour>=PARTY_HOURS)return;s.rep=clamp(s.rep-15);s.log.unshift('🛑 Soirée terminée avant l’heure : réputation -15.');s.waiting=false;s.decide=false;s.event=null;s.stage='summary';finish()}
function continueParty(){const extra=s.hour-PARTY_HOURS+1;s.decide=false;s.vig=clamp(s.vig+4+extra*3);s.log.unshift(`⏱️ Heure supplémentaire (${String(s.hour%24).padStart(2,'0')}h) : la vigilance grimpe.`);if(s.vig>=80&&(s.vig>=95||Math.random()<.5)){s.seized=true;s.busted=true;s.log.unshift('🚔 Les forces de l’ordre débarquent et saisissent le matériel !');return}drawEvent()}
function arrivalModal(){return `<div class="evmodal" id="evmodal"><div class="evbox"><div class="evcard arrivalcard"><div class="truckroad"><span class="truck">🚚</span></div><h1 class="eventtitle">Arrivée sur site en cours…</h1><p>${escapeHtml(s.spot.name)} · on décharge le matos</p><div class="loadbar"><i></i></div></div></div></div>`}
function bustedModal(){return `<div class="evmodal busted" id="evmodal"><div class="evbox"><div class="evcard bustedcard"><div class="bustedlights"></div><div class="bustedicon">🚔</div><h1 class="eventtitle bustedtitle">GAME OVER</h1><p>Les forces de l’ordre débarquent et saisissent tout le matériel. La soirée est terminée.</p><div class="choices"><button class="option choice" data-act="bustedend"><strong>📋 Voir le récap</strong><small>Bilan de la soirée</small></button></div></div></div></div>`}
function drawEvent(){const pr=probabilities(),r=Math.random()*100;const category=r<pr.problem?'problem':r<pr.problem+pr.positive?'positive':'neutral';s.lastCategory=category;s.event=rand((s.phase==='montage'?MONTAGE_EVENTS:EVENTS)[category])}
function eventEffect(e){if(e.sound<0&&s.stage==='party'){const worn=[...wallUnits(),...(s.rig.gen?[s.rig.gen]:[])].filter(u=>u.cond>0);if(worn.length){const u=rand(worn),slot=u.slot||'gen';u.cond=Math.max(0,u.cond-Math.round(-e.sound*1.5));s.log.unshift(`🔧 ${rigDef(slot,u.id).name} a pris cher (état ${u.cond}%).`)}}
s.money+=e.money||0;s.rep=clamp(s.rep+(e.rep||0));s.vig=clamp(s.vig+Math.max(0,e.vig||0));s.sound=clamp(s.sound+(e.sound||0));s.people=clamp(s.people+(e.people||0),0,cap());s.donations+=e.donation||0}
function arrivals(){const L=lineup();return Math.round((12+s.spot.appeal+s.rep*.16+rigStats().attract)*(.75+Math.random()*.5)*L.arrival*(s.infoline?1.3:1)*(.8+s.sound/250))}
function startParty(){const spot=s.spot,rs=rigStats();s.money-=spot.cost+rs.fuel;s.fuel=rs.fuel;s.phase='montage';s.mHour=0;s.hour=0;s.hist=[];s.decide=false;s.seized=false;s.busted=false;s.sound=rs.sound;s.infoline=false;s.people=0;s.totalPeople=0;s.donations=0;s.fines=0;s.result=null;s.log=[];s.vig=clamp(s.vig+Math.round(spot.risk/5));s.stage='party';s.waiting=false;s.arriving=true}
function launchInfoline(){if(s.infoline||s.money<INFOLINE_COST)return;s.money-=INFOLINE_COST;s.infoline=true;s.vig=clamp(s.vig+5);if(s.phase==='party')s.people=clamp(s.people+20,0,cap());s.log.unshift('📞 Infoline lancée : le bouche-à-oreille se répand.')}
function openDancefloor(){s.phase='party';s.hour=0;s.people=clamp(Math.round((30+s.spot.appeal+s.rep*.35+(s.infoline?35:0))*(.8+s.sound/250)),0,cap());s.totalPeople=s.people;s.donations+=Math.round(s.people*DON_PER_PERSON*(.8+Math.random()*.4)*lineup().don);s.log.unshift(`🎶 Le son est prêt (qualité ${s.sound}/100) : les portes ouvrent !`)}
function choose(index){if(!s.event)return;const choice=s.event.choices[index];if(!choice)return;eventEffect(choice.effect);const tag=s.phase==='montage'?`Montage ${s.mHour+1}/${MONTAGE_HOURS}`:`H${s.hour+1}`;s.log.unshift(`${tag} — ${s.event.title} : ${choice.label}`);(s.hist=s.hist||[]).push({k:s.lastCategory,i:evIcon(s.event),t:`${s.event.title} → ${choice.label} (${effectsLabel(choice.effect)})`});s.event=null;
if(s.phase==='montage'){s.mHour++;if(s.mHour>=MONTAGE_HOURS){s.phase='ready';return}advance();return}
s.hour++;const L=lineup();const exposure=Math.max(0,Math.round((s.spot.risk/14)+Math.max(0,s.people-150)/145+L.vigH));s.vig=clamp(s.vig+exposure);const before=s.people;if(s.hour>=11){const f=Math.min(.9,.12*Math.pow(1.8,s.hour-11));const gone=Math.round(s.people*f);s.people=Math.max(0,s.people-gone);if(gone)s.log.unshift(`🚶 ${gone} participants quittent la fête.`)}else s.people=clamp(s.people+arrivals(),0,cap());s.totalPeople=Math.max(s.totalPeople,s.people);s.donations+=Math.round(Math.max(0,s.people-before)*DON_PER_PERSON*(.8+Math.random()*.4)*L.don);
if(s.vig>=90&&Math.random()<.22){s.log.unshift('La fête doit être écourtée suite à un contrôle.');s.stage='summary';finish();return}advance()}
function effectsHtml(x){const v=[],f=(t,n,bad)=>`<span class="${(n>0)!==!!bad?'fxgood':'fxbad'}">${t}</span>`,sg=n=>n>0?'+':'';if(x.money)v.push(f(`💰 Caisse ${sg(x.money)}${euros(x.money)}`,x.money));if(x.rep)v.push(f(`🔥 Rep. ${sg(x.rep)}${x.rep}`,x.rep));if(x.vig)v.push(f(`👮 Vig. ${sg(x.vig)}${x.vig}`,x.vig,true));if(x.sound)v.push(f(`🔊 Quali. ${sg(x.sound)}${x.sound}`,x.sound));if(x.people)v.push(f(`👥 Publ. ${sg(x.people)}${x.people}`,x.people));if(x.donation)v.push(f(`💰 Dona. +${euros(x.donation)}`,x.donation));return v.join(' · ')}
function effectsLabel(x){const v=[];if(x.money)v.push(`Caisse ${x.money>0?'+':''}${euros(x.money)}`);if(x.rep)v.push(`Réputation ${x.rep>0?'+':''}${x.rep}`);if(x.vig>0)v.push(`Vigilance +${x.vig}`);if(x.sound)v.push(`Son ${x.sound>0?'+':''}${x.sound}`);if(x.people)v.push(`Public ${x.people>0?'+':''}${x.people}`);if(x.donation)v.push(`Donations +${euros(x.donation)}`);return v.join(' · ')}
function infolinePanel(){return `<div class="infoline">${s.infoline?`<p>📞 ✅ Infoline active : +30 % d’arrivées jusqu’à la fin de la soirée.</p>`:`<p class="tiny muted">📞 Infoline : +30 % d’arrivées et du public dès l’ouverture, mais +5 vigilance.</p>`}</div>`}
function infolineBtn(){return s.infoline?'':`<button class="btn" data-act="infoline" ${s.money<INFOLINE_COST?'disabled':''}>📞 Lancer l’infoline (${euros(INFOLINE_COST)})</button>`}
const WHEEL_N=12,WHEEL_ORDER=['neutral','problem','positive'],WHEEL_COL={neutral:'#6b6890',problem:'#c23d57',positive:'#2f9a6f'};
function wheelArcs(){const pr=probabilities(),N=24,cnt={},fr={};let tot=0;for(const k of WHEEL_ORDER){const x=pr[k]/100*N;cnt[k]=Math.max(pr[k]>0?1:0,Math.floor(x));fr[k]=x-Math.floor(x);tot+=cnt[k]}
while(tot<N){const k=WHEEL_ORDER.reduce((b,c)=>fr[c]>fr[b]?c:b);cnt[k]++;fr[k]=-1;tot++}
while(tot>N){const k=WHEEL_ORDER.reduce((b,c)=>cnt[c]>cnt[b]?c:b);cnt[k]--;tot--}
const put={neutral:0,problem:0,positive:0},sl=360/N,out=[];for(let i=0;i<N;i++){let best=null,bs=-1e9;for(const k of WHEEL_ORDER){if(put[k]>=cnt[k])continue;const sc=cnt[k]*(i+1)/N-put[k]-(out.length&&out[out.length-1].k===k?.5:0);if(sc>bs){bs=sc;best=k}}put[best]++;out.push({k:best,a0:i*sl,a1:(i+1)*sl})}return out}
function wheelSvg(){const R=140,C=150,sl=360/WHEEL_N;const pt=(a,r)=>[C+r*Math.sin(a*Math.PI/180),C-r*Math.cos(a*Math.PI/180)];let w='';const slices=wheelArcs();slices.forEach((S,i)=>{const k=S.k,a0=S.a0,a1=S.a1,sl=a1-a0,p0=pt(a0,R),p1=pt(a1,R),m=pt(a0+sl/2,R*.7);w+=`<path d="M${C} ${C}L${p0[0].toFixed(1)} ${p0[1].toFixed(1)}A${R} ${R} 0 0 1 ${p1[0].toFixed(1)} ${p1[1].toFixed(1)}Z" fill="${WHEEL_COL[k]}" stroke="#f3edff" stroke-width="2" opacity="${i%2?'.92':'1'}"/><text x="${m[0].toFixed(1)}" y="${m[1].toFixed(1)}" font-size="22" text-anchor="middle" dominant-baseline="central" transform="rotate(${a0+sl/2} ${m[0].toFixed(1)} ${m[1].toFixed(1)})">${CATS[k].emoji.replace('🟡','✌️').replace('🔴','💥').replace('🟢','🍀')}</text>`});
let bulbs='';for(let i=0;i<24;i++){const p=pt(i*15,R+7);bulbs+=`<circle class="bulb b${i%2}" cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="3.6"/>`}
return `<svg class="wheelsvg" viewBox="0 -8 300 150" aria-hidden="true"><circle cx="${C}" cy="${C}" r="${R+12}" fill="#2a1f4d" stroke="#f3edff" stroke-width="3"/><g id="wheelrot" style="transform-origin:150px 150px">${w}</g>${bulbs}<circle cx="${C}" cy="${C}" r="16" fill="#f3edff" stroke="#2a1f4d" stroke-width="4"/><path d="M150 4L138 -14H162Z" transform="translate(0 20)" fill="#ffd34e" stroke="#2a1f4d" stroke-width="3"/></svg>`}
function evIcon(e){const t=e.title.toLowerCase(),map=[[/agriculteur/,'🚜'],[/riverain|voisin|propriétaire/,'🏠'],[/danseurs|ambiance/,'💃'],[/enceinte|basses|câblage/,'🔊'],[/collecte|donation/,'🎁'],[/bénévoles/,'😴'],[/police|contrôle/,'🚓'],[/malaise/,'🚑'],[/harcèlement/,'🚨'],[/générateur|électrogène|câble/,'⚡'],[/terrain|orage/,'⛈️'],[/dj/,'🎧'],[/équipe/,'🤝'],[/lever/,'🌅'],[/accès/,'🗺️']];for(const [r,i] of map)if(r.test(t))return i;return CATS[s.lastCategory].emoji}
function eventModal(e,fx){const k=s.lastCategory;return `<div class="evmodal" id="evmodal"><div class="evbox">${fx?`<div class="wheelstage" id="wheelstage"><h2>🎡 La roue tourne…</h2><div class="wheelwrap">${wheelSvg()}</div><div class="wheelres" id="wheelres">&nbsp;</div></div>`:''}<div class="evcard ${fx?'hidden':''}" id="evcard">${(()=>{const late=s.phase==='party'&&s.hour>=PARTY_HOURS;const head=`<span class="eventtype ${k}">${CATS[k].label}</span><h1 class="eventtitle" data-type>${escapeHtml(e.title)}</h1>`;const ch=`<div class="choices">${e.choices.map((c,i)=>`<button class="option choice" data-act="choice" data-id="${i}"><strong>${escapeHtml(c.label)}</strong><small>${effectsHtml(c.effect)}</small></button>`).join('')}${late?`<button class="option choice" data-act="stopparty"><strong>🛑 Couper le son</strong><small>Fin de la soirée, bilan (l’événement est ignoré)</small></button>`:''}</div>`;const desc=`<p data-type>${escapeHtml(e.desc)}</p>`;return e.id?`<div class="evart ${k} hasimg"><span class="evicon">${evIcon(e)}</span><img class="evimg" src="img/events/${e.id}.webp" alt="" onload="this.parentNode.classList.add('loaded')" onerror="this.remove()"><div class="evov evtop">${head}</div><div class="evov evbot"><h3>Que fais-tu ?</h3>${ch}</div></div>${desc}`:`<div class="evart ${k}"><span class="evicon">${evIcon(e)}</span></div>${head}${desc}<h3>Que fais-tu ?</h3>${ch}`})()}</div></div></div>`}
function readyModal(){const ic=s.infoline;return `<div class="evmodal" id="evmodal"><div class="evbox"><div class="evcard"><div class="evart neutral"><span class="evicon">📞</span></div><span class="eventtype neutral">Son monté</span><h1 class="eventtitle" data-type>${ic?'Infoline lancée !':'Lance l’infoline !'}</h1><p data-type>${ic?'Le bouche-à-oreille tourne : tu peux ouvrir les portes.':`Le son est monté (qualité ${s.sound}/100). Avant d’ouvrir, prévient le public : +30 % d’arrivées et du public dès l’ouverture, mais +5 vigilance.`}</p><div class="choices">${ic?'':`<button class="option choice" data-act="infoline" ${s.money<INFOLINE_COST?'disabled':''}><strong>📞 Lancer l’infoline</strong><small>${euros(INFOLINE_COST)} · Vigilance +5 · Arrivées +30 %</small></button>`}<button class="option choice" data-act="opendoors"><strong>🎶 Ouvrir les portes${ic?'':' sans infoline'}</strong><small>La première heure de fête commence</small></button></div></div></div></div>`}
function skyColor(hc){const x=hc>=22?0:Math.max(0,Math.min(1,(hc-4)/6)),a=[64,110,190],b=[255,179,71];return `rgb(${a.map((v,j)=>Math.round(v+(b[j]-v)*x)).join(',')})`}
function timeline(){const h=s.hist||[],M=MONTAGE_HOURS,P=PARTY_HOURS,total=Math.max(M+P,h.length+1);let o='<div class="tl">',sky='<div class="sky">';for(let i=0;i<total;i++){const e=h[i],base=i<M?'🛠️':'🔊',hc=i<M?22+i:(i-M)%24;const k=e?e.k:i<M?'neutral':'base';o+=`<div class="tls ${k}${i===h.length?' cur':''}${i===M?' sep':''}"${e&&e.t?` title="${escapeHtml(e.t)}"`:''}><i>${e?e.i:base}</i><b>${String(hc).padStart(2,'0')}h</b></div>`;sky+=`<span style="background:${skyColor(hc)}"></span>`}return `<div class="skyrow"><span>🌙</span>${sky}</div><span>☀️</span></div>`+o+'</div>'}
function decideModal(){const x=s.hour-PARTY_HOURS+1,hh=String(s.hour%24).padStart(2,'0');return `<div class="evmodal" id="evmodal"><div class="evbox"><div class="evcard"><div class="evart neutral"><span class="evicon">⏰</span></div><span class="eventtype neutral">${hh}h</span><h1 class="eventtitle" data-type>${x===1?'La soirée touche à sa fin':'Encore une heure ?'}</h1><p data-type>Tu peux couper le son ici ou continuer. Chaque heure supplémentaire fait grimper la vigilance (+${4+x*3}) et, passé un certain seuil, les forces de l’ordre peuvent tout saisir et mettre fin à la soirée.</p><p class="tiny muted">Vigilance actuelle : ${s.vig}/100</p><div class="choices"><button class="option choice" data-act="stopparty"><strong>🛑 Couper le son</strong><small>Fin de la soirée, bilan</small></button><button class="option choice" data-act="goon"><strong>🔥 Continuer une heure de plus</strong><small>Vigilance +${4+x*3} · risque de saisie</small></button></div></div></div></div>`}
function party(fx){const pr=probabilities(),e=s.event,L=lineup(),ready=s.phase==='ready',montage=s.phase==='montage'||ready;
const title=ready?`🔊 Son monté — ${s.spot.name} — 00h · Prêt à ouvrir`:montage?`🔧 Montage du son — ${s.spot.name} — ${String((22+s.mHour)%24).padStart(2,'0')}h · Étape ${s.mHour+1}/${MONTAGE_HOURS}`:s.decide?`🎛️ ${s.spot.name} — ${String(s.hour%24).padStart(2,'0')}h · Fin de soirée`:`🎛️ ${s.spot.name} — ${String(s.hour%24).padStart(2,'0')}h · ${s.hour<PARTY_HOURS?`Tour ${s.hour+1}/${PARTY_HOURS}`:`Heure sup +${s.hour-PARTY_HOURS+1}`}`;
const pct=ready?100:montage?s.mHour/MONTAGE_HOURS*100:s.hour/PARTY_HOURS*100;
const metrics=`<div class="metric"><span>${L.emoji} Line up</span><b>${L.name}</b></div><div class="metric"><span>🔊 Qualité du son</span><b>${s.sound}/100</b></div>`+(montage?`<div class="metric"><span>📞 Infoline</span><b>${s.infoline?'Lancée':'Non lancée'}</b></div>`:`<div class="metric"><span>👥 Participants sur place</span><b>${s.people}</b></div><div class="metric"><span>🎁 Donations cumulées</span><b>${euros(s.donations)}</b></div>`);
return card(title,timeline())+`<section class="panel stagepanel" id="stage">${s.arriving?arrivalModal():s.busted?bustedModal():e?eventModal(e,fx):ready?readyModal():s.decide?decideModal():''}</section>`+card('📊 Situation',`<div class="split"><div>${metrics}</div><div><div class="metric"><span>🟡 Neutre</span><b>${pr.neutral.toFixed(0)} %</b></div><div class="metric"><span>🔴 Problème</span><b>${pr.problem.toFixed(0)} %</b></div><div class="metric"><span>🟢 Positif</span><b>${pr.positive.toFixed(0)} %</b></div><p class="probnote">Probabilité du prochain tirage selon ta réputation${montage?'':', ta vigilance et ton line up'}</p></div></div>${infolinePanel()}<div class="endrow">${infolineBtn()}${(()=>{const late=s.phase==='party'&&s.hour>=PARTY_HOURS;return `<button class="btn danger-btn" data-act="endearly" ${late?'disabled':''} title="${late?'Disponible avant 12h uniquement : utilise « Couper le son »':'Gros malus de réputation (-15)'}">🛑 Terminer la soirée</button>`})()}</div>`)
+`<details class="panel logpanel" ${showLog?'open':''} ontoggle="window.__log(this.open)"><summary><h2>📋 Journal de la soirée</h2><span class="logcount">${s.log.length} entrée${s.log.length>1?'s':''}</span></summary><div class="log">${s.log.length?s.log.slice(0,10).map(x=>`<div>${escapeHtml(x)}</div>`).join(''):'Le montage commence : place aux imprévus !'}</div></details>`}
let showLog=false;window.__log=o=>{showLog=o};
function finish(){if(s.result)return;const crowd=s.totalPeople;const fine=s.vig>=75?Math.round(80+(s.vig-75)*9):0;s.fines=fine;s.money+=s.donations-fine;const bonus=(crowd>160?3:0)-(s.vig>75?7:0);s.rep=clamp(s.rep+bonus);const wearMap={};const mult=s.lineup==='hardcore'?1.3:1;for(const u of [...wallUnits(),...(s.rig.gen?[s.rig.gen]:[])]){const name=rigDef(u.slot||'gen',u.id).name;const loss=Math.min(u.cond,Math.round((6+Math.random()*8)*mult));u.cond-=loss;const w=wearMap[name]||(wearMap[name]={n:0,loss:0,low:0});w.n++;w.loss+=loss;if(u.cond<=30)w.low++}
const wear=s.seized?['🚔 TOUT LE MATÉRIEL A ÉTÉ SAISI']:Object.entries(wearMap).map(([n,w])=>`${n}${w.n>1?' ×'+w.n:''} −${Math.round(w.loss/w.n)}%${w.low?` (${w.low} à renouveler)`:''}`);
s.result={donations:s.donations,fine,people:crowd,bonus,wear,fuel:s.fuel||0,net:s.donations-fine-s.spot.cost-(s.fuel||0)};if(s.seized){s.seizures.push({week:s.week,items:wallUnits().map(u=>({slot:u.slot,id:u.id,cond:u.cond})),gen:s.rig.gen,status:'nonews'});s.judgeNew=true;s.rig={gen:null};s.wall={top:[],kick:[],sub2:[],sub:[]};s.rigDone=false}}
function summary(){const r=s.result;return card('🌅 Fin de la free party',`<p data-type>Soirée ${lineup().name} terminée (ou écourtée). Voici le bilan du week-end n° ${s.week}.</p><div class="gearbanner ${s.seized?'lost':'safe'}">${s.seized?'🚔 Le matériel a été saisi':'🏠 Le matos est rentré au chaud'}</div><div class="split"><div><div class="metric"><span>👥 Pic de fréquentation</span><b>${r.people} personnes</b></div><div class="metric"><span>🎁 Donations</span><b class="good">+${euros(r.donations)}</b></div><div class="metric"><span>🧰 Installation</span><b>−${euros(s.spot.cost)}</b></div><div class="metric"><span>⛽ Carburant</span><b>−${euros(r.fuel)}</b></div><div class="metric"><span>⚖️ Amendes éventuelles</span><b class="danger">−${euros(r.fine)}</b></div></div><div><div class="metric"><span>📊 Solde de la fête (hors décisions)</span><b>${euros(r.net)}</b></div><div class="metric"><span>🔥 Ajustement réputation</span><b>${r.bonus>=0?'+':''}${r.bonus}</b></div><div class="metric"><span>👮 Vigilance finale</span><b>${s.vig}/100</b></div><div class="metric"><span>💰 Caisse actuelle</span><b>${euros(s.money)}</b></div></div></div><div class="info">🔧 Usure du matos : ${r.wear.length?r.wear.join(' · '):'aucun matériel'}. Pense à réparer ou remplacer avant la prochaine soirée.</div><div class="info">Le bilan comprend les dons et les amendes ; les dépenses et recettes liées aux décisions ont été appliquées immédiatement pendant la fête.</div><div class="toolbar"><button class="btn secondary" data-act="postsocial" ${r.posted?'disabled':''}>${r.posted?'📱 Publié sur les réseaux (+4 réputation, +6 vigilance)':'📱 Poster sur les réseaux (+4 réputation, +6 vigilance)'}</button><button class="btn nextweek" data-act="nextweek">Semaine suivante : +${euros(s.salary)} de salaire →</button></div>`)}

// --- Animations : texte machine à écrire et tirage façon machine à sous ---
let lastKey='',lastStage='',fxToken=0,arrTimer=0;
async function typeEls(els,token){const items=els.map(el=>({el,text:el.textContent}));items.forEach(i=>{i.el.textContent='';i.el.classList.add('typing')});const start=performance.now();let done=false;while(!done){await sleep(16);if(token!==fxToken)return;const n=Math.floor((performance.now()-start)/9);done=true;for(const i of items){i.el.textContent=i.text.slice(0,n);if(n<i.text.length)done=false}}items.forEach(i=>i.el.classList.remove('typing'))}
function burst(k){const w=$('.wheelwrap');if(!w)return;const col={neutral:['#ffd34e','#c9c5f2'],problem:['#ff7d93','#ffb347'],positive:['#6fe3b0','#c4f85b']}[k],em={neutral:'✌️',problem:'💥',positive:'🍀'}[k];const ring=document.createElement('i');ring.className='ring';ring.style.setProperty('--c',col[0]);w.appendChild(ring);
for(let i=0;i<44;i++){const p=document.createElement('i'),a=Math.random()*Math.PI,d=70+Math.random()*190,em2=i%7===0;p.className=em2?'pt emo':'pt';if(em2)p.textContent=em;else p.style.setProperty('--c',col[i%2]);p.style.setProperty('--dx',(Math.cos(a)*d*(Math.random()<.5?-1:1)).toFixed(0)+'px');p.style.setProperty('--dy',(-Math.sin(a)*d*.8+30).toFixed(0)+'px');p.style.animationDelay=(Math.random()*.12).toFixed(2)+'s';w.appendChild(p)}
setTimeout(()=>w.querySelectorAll('.pt,.ring').forEach(n=>n.remove()),1600)}
async function runSlot(token){const rot=$('#wheelrot'),res=$('#wheelres');if(!rot)return;const k=s.lastCategory,A=rand(wheelArcs().filter(x=>x.k===k)),target=360*6+360-(A.a0+(A.a1-A.a0)*(.12+Math.random()*.76));
await sleep(350);placeModal();if(token!==fxToken)return;rot.style.transition='transform 4.6s cubic-bezier(.12,.62,.08,1)';rot.style.transform=`rotate(${target}deg)`;await sleep(4800);if(token!==fxToken)return;
res.className='wheelres '+k;res.textContent=`${CATS[k].emoji} ${CATS[k].label} !`;burst(k);$('#wheelstage').classList.add('shake');await sleep(1500);if(token!==fxToken)return;
$('#wheelstage').classList.add('hidden');$('#evcard').classList.remove('hidden');placeModal();await typeEls([...document.querySelectorAll('#evcard [data-type]')],token)}
function placeModal(){const m=$('#stage');if(m)m.scrollIntoView({block:'nearest',behavior:'instant'})}
function render(){const key=[s.stage,s.setupStep,s.phase,s.mHour,s.hour,s.decide,s.busted,s.week,s.event&&s.event.title].join('|');const fx=key!==lastKey&&!reduceMotion;lastKey=key;
const body=s.stage==='setup'?setup():s.stage==='hideout'?hideout():s.stage==='map'?map():s.stage==='lineup'?lineupStage():s.stage==='party'?party(fx&&!!s.event):summary();
$('#game').innerHTML=header()+body+`<div class="foot">Prototype indépendant — fiction. Contrôles : clic/touch • Sauvegarde locale automatique • Fond 3D PlayCanvas (connexion nécessaire).</div>`+judgeModal();
const token=++fxToken;placeModal();if(s.stage!==lastStage){lastStage=s.stage;window.scrollTo(0,0)}if(s.arriving&&!arrTimer)arrTimer=setTimeout(()=>{arrTimer=0;if(!s.arriving)return;s.arriving=false;nextEvent();save();render()},reduceMotion?1200:2800);if(!fx)return;
if(s.stage==='setup'||s.stage==='hideout'){const p=document.querySelector('#game .panel');if(p)p.classList.add('stepfade')}
const els=[...document.querySelectorAll('#game [data-type]')].filter(el=>!el.closest('#evcard'));typeEls(els,token);
if(s.stage==='party'&&s.event)runSlot(token)}

document.addEventListener('input',e=>{if(e.target.id!=='crew')return;s.crew=e.target.value.slice(0,32);const b=$('#startbtn');if(b)b.disabled=!s.crew.trim();const ok=!!s.crew.trim();e.target.classList.toggle('invalid',!ok);const h=$('#crewhint');if(h)h.hidden=ok;save()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const id=b.dataset.id;
switch(b.dataset.act){
case'reset':if(!confirm('Effacer la sauvegarde et recommencer ?'))return;s=fresh();break;
case'randname':s.crew=randomCrewName();break;
case'avatar':if(!AVATARS.includes(id))return;s.avatar=id;break;
case'rigbuy':{const [slot,did]=String(id).split(':'),def=rigDef(slot,did);if(!def)return;const used=b.dataset.mode==='used',cond=used?usedCond(id):100,price=used?usedPrice(def,cond):def.price;if(s.money<price)return;
if(slot==='gen'){const old=s.rig.gen,od=old&&rigDef('gen',old.id);if(od)s.money+=sellPrice(od,old.cond);s.rig.gen={id:did,cond}}
else{if(!canPlace(slot,did))return;s.wall[slot==='sub'?'sub2':slot].push({slot,id:did,cond});if(slot==='sub'){balanceSubs();s.sel=null}}
s.money-=price;delete s.used[id];break}
case'rigdone':if(!rigReady())return;s.rigDone=true;s.sel=null;break;
case'rigedit':s.rigDone=false;break;
case'unitsel':s.sel=s.sel===id?null:id;break;
case'rigrepair':{const t=selTarget();if(!t)return;const def=rigDef(t.slot,t.obj.id),cost=repairCost(def,t.obj.cond);if(t.obj.cond>=100||s.money<cost)return;s.money-=cost;t.obj.cond=100;break}
case'repairall':{const all=[...wallUnits(),...(s.rig.gen?[s.rig.gen]:[])];let cost=0;for(const u of all)cost+=repairCost(rigDef(u.slot||'gen',u.id),u.cond);if(cost<=0||s.money<cost)return;s.money-=cost;all.forEach(u=>u.cond=100);break}
case'rigsell':{const t=selTarget();if(!t)return;s.money+=sellPrice(rigDef(t.slot,t.obj.id),t.obj.cond);if(t.slot==='gen')s.rig.gen=null;else s.wall[t.r].splice(t.i,1);if(t.slot==='sub')balanceSubs();s.sel=null;break}
case'setupnext':if(!s.crew.trim())return;s.crew=s.crew.trim();s.setupStep=2;break;
case'setupback':s.setupStep=1;break;
case'startcrew':if(!s.crew.trim()||!rigReady())return;s.crew=s.crew.trim();s.rigDone=true;s.sel=null;s.stage='hideout';break;
case'tomap':s.stage='map';break;
case'back':s.stage='hideout';break;
case'spot':{const spot=SPOTS.find(x=>x.id===id);if(!spot||!rigReady()||s.money<spot.cost+rigStats().fuel)return;s.spot=spot;s.stage='lineup';break}
case'lineup':{if(!LINEUPS.some(l=>l.id===id)||!s.spot||!rigReady()||s.money<s.spot.cost+rigStats().fuel)return;s.lineup=id;startParty();break}
case'infoline':{const was=s.phase==='ready';launchInfoline();if(was&&s.infoline){openDancefloor();nextEvent()}break}
case'opendoors':openDancefloor();nextEvent();break;
case'bustedend':s.busted=false;s.stage='summary';finish();break;
case'stopparty':stopParty();break;
case'endearly':endEarly();break;
case'goon':continueParty();break;
case'choice':choose(Number(id));break;
case'postsocial':if(s.result&&!s.result.posted){s.result.posted=true;s.rep=clamp(s.rep+4);s.vig=clamp(s.vig+6);s.log.unshift('📱 Post sur les réseaux : réputation +4, vigilance +6.')}break;
case'judge':showJudge=true;s.judgeNew=false;break;
case'judgeclose':showJudge=false;break;
case'nextweek':advanceCases();s.week++;s.used={};s.money+=s.salary;s.vig=clamp(s.vig-3);s.result=null;s.event=null;s.spot=null;s.lineup=null;s.stage='hideout';break}
save();render()});
if(s.waiting){s.waiting=false;if(s.stage==='party'&&!s.event&&!s.arriving&&!s.busted&&!s.decide)nextEvent()}
render();
